class FinancialAccountType(DjangoObjectType):
    class Meta:
        model = FinancialAccount
        fields = ('id', 'account_number', 'account_type')

    transaction_record = graphene.Field(TransactionType, transaction_id=graphene.Int(required=True))

    def resolve_transaction_record(self, info, transaction_id):
        user = info.context.user
        if not user.is_authenticated or self.owner != user:
            raise GraphQLError("Access denied.")
        return self.transactions.filter(id=transaction_id).first()
